CREATE TABLE customer_bicycles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid REFERENCES customers(id) ON DELETE SET NULL,nickname text,brand text,model text,year integer,bike_type text,color text,wheel_size text,serial_number text,frame_number text,notes text,photo_url text,status varchar(20) NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),created_by uuid REFERENCES administrators(id) ON DELETE SET NULL,updated_by uuid REFERENCES administrators(id) ON DELETE SET NULL,deleted_at timestamptz);CREATE INDEX bicycles_customer_idx ON customer_bicycles(customer_id);
CREATE TABLE workshop_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_number varchar(40) NOT NULL UNIQUE,customer_id uuid REFERENCES customers(id) ON DELETE SET NULL,bicycle_id uuid REFERENCES customer_bicycles(id) ON DELETE SET NULL,customer_name text NOT NULL,customer_phone varchar(20) NOT NULL,customer_email varchar(254),bike_brand text,bike_model text,bike_type text,problem_description text NOT NULL,preferred_contact_method varchar(20) NOT NULL,status varchar(20) NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,reviewed_by uuid REFERENCES administrators(id) ON DELETE SET NULL,converted_order_id uuid,rejection_reason text);CREATE INDEX workshop_requests_status_idx ON workshop_requests(status);
CREATE TABLE workshop_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_number varchar(40) NOT NULL UNIQUE,customer_id uuid NOT NULL REFERENCES customers(id) ON DELETE RESTRICT,bicycle_id uuid NOT NULL REFERENCES customer_bicycles(id) ON DELETE RESTRICT,request_id uuid REFERENCES workshop_requests(id) ON DELETE SET NULL,status varchar(30) NOT NULL DEFAULT 'received',priority varchar(20) NOT NULL DEFAULT 'normal',problem_description text NOT NULL,initial_diagnosis text,internal_notes text,customer_visible_summary text,estimated_completion_at timestamptz,ready_at timestamptz,delivered_at timestamptz,cancelled_at timestamptz,cancellation_reason text,subtotal_services_cents integer NOT NULL DEFAULT 0,subtotal_parts_cents integer NOT NULL DEFAULT 0,discount_cents integer NOT NULL DEFAULT 0,total_cents integer NOT NULL DEFAULT 0,amount_paid_cents integer NOT NULL DEFAULT 0,payment_status varchar(20) NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),created_by uuid REFERENCES administrators(id) ON DELETE SET NULL,updated_by uuid REFERENCES administrators(id) ON DELETE SET NULL,assigned_to uuid REFERENCES administrators(id) ON DELETE SET NULL);CREATE INDEX workshop_orders_status_idx ON workshop_orders(status);CREATE INDEX workshop_orders_customer_idx ON workshop_orders(customer_id);ALTER TABLE workshop_requests ADD FOREIGN KEY(converted_order_id) REFERENCES workshop_orders(id) ON DELETE SET NULL;
CREATE TABLE workshop_order_services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workshop_order_id uuid NOT NULL REFERENCES workshop_orders(id) ON DELETE CASCADE,service_name text NOT NULL,description text,quantity integer NOT NULL DEFAULT 1,unit_price_cents integer NOT NULL DEFAULT 0,total_cents integer NOT NULL DEFAULT 0,status varchar(20) NOT NULL DEFAULT 'pending',is_customer_visible boolean NOT NULL DEFAULT true,performed_by uuid REFERENCES administrators(id) ON DELETE SET NULL,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(quantity>0 AND unit_price_cents>=0));CREATE INDEX workshop_services_order_idx ON workshop_order_services(workshop_order_id);
CREATE TABLE workshop_order_parts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workshop_order_id uuid NOT NULL REFERENCES workshop_orders(id) ON DELETE CASCADE,product_id uuid,part_name text NOT NULL,brand text,sku text,description text,quantity integer NOT NULL DEFAULT 1,unit_price_cents integer NOT NULL DEFAULT 0,total_cents integer NOT NULL DEFAULT 0,status varchar(20) NOT NULL DEFAULT 'planned',is_customer_visible boolean NOT NULL DEFAULT true,installed_at timestamptz,installed_by uuid REFERENCES administrators(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(quantity>0 AND unit_price_cents>=0));CREATE INDEX workshop_parts_order_idx ON workshop_order_parts(workshop_order_id);
CREATE TABLE workshop_status_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workshop_order_id uuid NOT NULL REFERENCES workshop_orders(id) ON DELETE CASCADE,previous_status text,new_status text NOT NULL,public_message text,internal_reason text,changed_by uuid REFERENCES administrators(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),customer_visible boolean NOT NULL DEFAULT true);CREATE INDEX workshop_history_order_idx ON workshop_status_history(workshop_order_id,created_at);
CREATE TABLE workshop_customer_updates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workshop_order_id uuid NOT NULL REFERENCES workshop_orders(id) ON DELETE CASCADE,title text NOT NULL,message text NOT NULL,progress_percent integer,photo_url text,customer_visible boolean NOT NULL DEFAULT true,created_by uuid REFERENCES administrators(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(progress_percent IS NULL OR progress_percent BETWEEN 0 AND 100));CREATE INDEX workshop_updates_order_idx ON workshop_customer_updates(workshop_order_id,created_at);
CREATE TABLE workshop_public_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workshop_order_id uuid NOT NULL REFERENCES workshop_orders(id) ON DELETE CASCADE,token_hash varchar(64) NOT NULL UNIQUE,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),last_used_at timestamptz,expires_at timestamptz,revoked_at timestamptz);CREATE INDEX workshop_tokens_order_idx ON workshop_public_tokens(workshop_order_id);
CREATE TABLE workshop_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workshop_order_id uuid NOT NULL REFERENCES workshop_orders(id) ON DELETE CASCADE,channel varchar(20) NOT NULL,recipient text NOT NULL,template_key text,message_preview text,status varchar(20) NOT NULL,external_reference text,error_code text,created_at timestamptz NOT NULL DEFAULT now(),sent_at timestamptz,created_by uuid REFERENCES administrators(id) ON DELETE SET NULL);CREATE INDEX workshop_notifications_order_idx ON workshop_notifications(workshop_order_id);
CREATE TABLE workshop_settings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),public_requests_enabled boolean NOT NULL DEFAULT true,public_tracking_enabled boolean NOT NULL DEFAULT true,allow_customer_photos boolean NOT NULL DEFAULT false,default_estimated_days integer,ready_whatsapp_template text NOT NULL,status_whatsapp_templates jsonb NOT NULL DEFAULT '{}',public_status_labels jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid REFERENCES administrators(id) ON DELETE SET NULL);CREATE UNIQUE INDEX workshop_settings_singleton_idx ON workshop_settings((true));
